import { NotationData } from '../types';

/**
 * Converts structured Apollo NotationData (generated by Music21) into AlphaTex.
 * AlphaTex is natively parsed by AlphaTab for publication-quality SVG score and tab rendering.
 */
export function convertNotationToAlphaTex(notation: NotationData): string {
  const tempo = notation.metadata.tempo || 120;
  
  // Parse time signature (e.g. "4/4" -> 4 4)
  let numBeats = 4;
  let beatValue = 4;
  if (notation.metadata.time_signature && notation.metadata.time_signature.includes('/')) {
    const parts = notation.metadata.time_signature.split('/');
    numBeats = parseInt(parts[0], 10) || 4;
    beatValue = parseInt(parts[1], 10) || 4;
  }

  const isBass = notation.stem === 'bass';
  const clef = isBass ? '\\clef bass' : '\\clef treble';
  const tuning = isBass ? '\\tuning G2 D2 A1 E1' : '\\tuning E4 B3 G3 D3 A2 E2';

  let tex = `\\tempo ${tempo} \\ts ${numBeats} ${beatValue} ${clef} ${tuning}\n`;

  // Duration mapping helper
  const getDurationCode = (quarterLength: number): string => {
    if (quarterLength >= 3.5) return ':1'; // Whole note
    if (quarterLength >= 1.75) return ':2'; // Half note
    if (quarterLength >= 0.85) return ':4'; // Quarter note
    if (quarterLength >= 0.4) return ':8'; // Eighth note
    return ':16'; // Sixteenth note
  };

  notation.measures.forEach((measure) => {
    let barStr = '';

    if (!measure.notes || measure.notes.length === 0) {
      tex += ':1 r |\n';
      return;
    }

    measure.notes.forEach((note) => {
      const durCode = getDurationCode(note.duration);

      if (note.is_rest) {
        barStr += `${durCode} r `;
      } else if (note.is_chord && note.pitches && note.pitches.length > 0) {
        // Chord representation: (fret.string fret.string)
        const chordNotes = note.pitches
          .map((p) => `${p.fret}.${p.string}`)
          .join(' ');
        barStr += `${durCode} (${chordNotes}) `;
      } else if (note.string && note.fret !== undefined) {
        barStr += `${durCode} ${note.fret}.${note.string} `;
      } else {
        barStr += `${durCode} 0.${isBass ? 4 : 6} `;
      }
    });

    tex += `${barStr.trim()} |\n`;
  });

  return tex;
}
